    # SQLite (development and the test suite): the same fields in Python.
    Run = apps.get_model('scoring', 'CapabilityRun')
    Event = apps.get_model('scoring', 'CapabilityRunEvent')
    View = apps.get_model('scoring', 'CapabilityRunView')
